package contract

// #3094 (#3088), seat:caa's stored-verdict table (research 0030; the exemption rule for ADR 0035 D1).
// Before #3094 the encoder wrote a nil value as the empty tuple (FromValue's nil sentinel), so a
// derivation holding nil was stored under the digest of the account holding (). For every such shape
// that stored a verdict (cca's census on #3094, measured on main): rows 10 and 17 stored rejects, and
// rows 22 and 26 stored accepts. Row 8 panicked and stored nothing.
//
// Each row's account is a hand-authored negation.json case whose expected verdict is the spec's, and
// every core replays it (rs, go, ts). This test pins the case to the account the stored verdict is
// keyed by: the case's bytes must EQUAL the pre-fix bytes of the nil shape, measured on main 5b5bfbea
// with the pre-fix encoder. So the replay compares the stored verdict with a correct check of the very
// account those bytes name. Every row reads equal, which proves the no-bump exemption by this table.

import (
	"encoding/hex"
	"testing"
)

// storedVerdictRows3094 are the pre-fix bytes (EncodeDerivationWireV1 on main 5b5bfbea) of each nil
// shape, by the negation.json case that is the account they name.
var storedVerdictRows3094 = []struct{ name, prefixHex string }{
	{"stored_verdict_3094_row10_the_empty_tuple_in_a_builtin_conclusion",
		"0102001f70726f6f662d696e7465726368616e67652f64657269766174696f6e2f763101020102010200076275696c74696e0102000473765f71010200010101000106000472756c650102000473765f700102000100000161000473765f72010101020001580102000100000161010101020003696e74000100010100046e6f6e6501020003696e7400020001"},
	{"stored_verdict_3094_row17_the_empty_tuple_in_a_neg_premise_atom",
		""},
	{"stored_verdict_3094_row22_the_empty_tuple_in_an_uncited_support_edge_fact",
		""},
	{"stored_verdict_3094_row26_the_empty_tuple_in_an_uncited_support_ref_atom",
		""},
}

func TestEachStoredVerdictCaseIsTheAccountItsPreFixBytesName3094(t *testing.T) {
	vf := loadNegVectors(t)
	derived := NewCertContext(Hash{}, negVectorPin(1), negVectorPin(2), negVectorPin(3))
	for _, row := range storedVerdictRows3094 {
		var found *negCase
		for i := range vf.Cases {
			if vf.Cases[i].Name == row.name {
				found = &vf.Cases[i]
			}
		}
		if found == nil {
			t.Fatalf("negation.json has no case %s", row.name)
		}
		nodes := make([]Node, len(found.Derivation.Nodes))
		for i, nj := range found.Derivation.Nodes {
			nodes[i] = nj.build(t)
		}
		world := make([]ClosedModelCert, len(found.Derivation.ClosedWorld))
		for i, cj := range found.Derivation.ClosedWorld {
			world[i] = cj.build(t, derived)
		}
		var deriv Derivation
		if len(world) == 0 {
			deriv = NewDerivation(nodes, uint64(found.Derivation.Root))
		} else {
			deriv = NewDerivationWithClosedWorld(nodes, uint64(found.Derivation.Root), world)
		}
		got := hex.EncodeToString(EncodeDerivationWireV1(deriv))
		if got != row.prefixHex {
			t.Errorf("%s: the case encodes to\n  %s\nnot the pre-fix bytes it must be the account of\n  %s", row.name, got, row.prefixHex)
		}
	}
}
